#include <stdio.h> // นำเข้าไลบรารีพื้นฐานสำหรับการรับและแสดงผล (Standard Input/Output)

// จุดเริ่มต้นของโปรแกรม
int main() {

    // เขียนโค้ดของเราตรงนี้

    return 0; // จบการทำงานของฟังก์ชัน main
}

#include <stdio.h>

int main() {
    printf("Hello CBC Boost Camp!\n"); // \n (Backslash n) ใช้สำหรับขึ้นบรรทัดใหม่

    printf("My name is ...\n");
    return 0;
}

#include <stdio.h>

int main() {
    int age; // สร้างตัวแปรมารอรับค่าอายุ (เป็นตัวเลขจำนวนเต็ม)

    printf("How old are you?: "); 

    // สำหรับ scanf ต้องมี & (Ampersand) นำหน้าชื่อตัวแปร เพื่อชี้ที่อยู่ของข้อมูล
    scanf("%d", &age); 

    printf("Wow, you are %d years old!\n", age);
    return 0;
}

#include <stdio.h>

int main() {
    int score = 100;
    float gpa = 3.99;
    char grade = 'A';

    printf("Score: %d\n", score);
    printf("GPA: %.2f\n", gpa); // %.2f หมายถึง แสดงทศนิยม 2 ตำแหน่ง
    printf("Grade: %c\n", grade);
    return 0;
}

#include <stdio.h>

int main() {
    int a = 10;
    int b = 3;

    // คำนวณแล้วเก็บผลลัพธ์ไว้ในตัวแปรใหม่
    int sum = a + b;
    int difference = a - b;
    int quotient = a / b;
    int remainder = a % b;

    printf("10 + 3 = %d\n", sum);
    printf("10 - 3 = %d\n", difference);
    printf("10 / 3 = %d (การหาร int ได้ผลลัพธ์แบบปัดเศษทิ้ง)\n", quotient);
    printf("10 %% 3 = %d (ใช้หาเศษจากการหาร)\n", remainder); // พิมพ์ %% เพื่อแสดงเครื่องหมาย %
    return 0;
}

#include <stdio.h>

int main() {
    int money = 50;

    // โปรแกรมจะตรวจสอบจากบนลงล่าง หากเจอเงื่อนไขที่เป็นจริง จะทำงานแล้วจบเงื่อนไขทันที
    if (money >= 100) {
        printf("กินชาบู\n");
    } else if (money >= 50) {
        printf("กินกะเพรา\n");
    } else {
        printf("กินมาม่า\n");
    }
    return 0;
}

#include <stdio.h>

int main() {
    int i = 0; // กำหนดจุดเริ่มต้น

    while (i < 5) { // ตรวจสอบเงื่อนไข
        printf("%d\n", i);
        i++; // สำคัญ: ต้องมีการอัปเดตค่าเสมอ มิฉะนั้นลูปจะไม่จบการทำงาน (Infinity Loop)
    }
    return 0;
}

#include <stdio.h>

int main() {
    // for (เริ่มต้น ; ตรวจสอบเงื่อนไข ; อัปเดตค่า)
    for (int i = 5; i > 0; i--) {
        printf("เหลือเวลา %d วินาที\n", i);
    }
    printf("หมดเวลา!\n");
    return 0;
}

#include <stdio.h>

int main() {
    // สร้าง Array ชื่อ scores เก็บข้อมูลชนิด int จำนวน 5 ค่า
    int scores[5] = {10, 20, 30, 40, 50};

    printf("คะแนนคนที่ 1 (Index 0): %d\n", scores[0]);
    printf("คะแนนคนที่ 5 (Index 4): %d\n", scores[4]);

    // เรานิยมใช้ For Loop ร่วมกับ Array เพื่อเข้าถึงข้อมูลทุกตัว
    for(int i = 0; i < 5; i++) {
        printf("คะแนนคนที่ %d: %d\n", i+1, scores[i]);
    }
    return 0;
}

#include <stdio.h>

int main() {
    // จองพื้นที่ 20 ช่องสำหรับเก็บข้อความ (รวมช่องว่างและตัวอักษรพิเศษ \0 ที่ใช้ปิดท้าย String)
    char name[20]; 

    printf("Enter your name: ");
    // การรับค่า String ด้วย scanf ไม่ต้องใส่ & นำหน้าตัวแปร
    scanf("%s", name); 

    // เวลาแสดงผล String เราจะใช้ %s
    printf("Welcome, %s!\n", name);
    return 0;
}

#include <stdio.h>

// 1. ฟังก์ชันแบบ "ไม่คืนค่า" (ระบุชนิดเป็น void)
// ใช้เมื่อต้องการให้ฟังก์ชันทำงานบางอย่างให้เสร็จสิ้นโดยไม่ต้องส่งค่ากลับมา
void say_hello() {
    printf("Hello CBC!\n");
}

// 2. ฟังก์ชันแบบ "คืนค่า" (ระบุชนิดข้อมูล เช่น int)
// ใช้เมื่อต้องการให้ฟังก์ชันคำนวณและส่งผลลัพธ์กลับมาให้โปรแกรมหลักใช้งานต่อ
int add(int a, int b) {
    int result = a + b;
    return result; // คืนค่าผลลัพธ์กลับไป
}

int main() {
    say_hello(); // เรียกใช้งานฟังก์ชัน say_hello

    // เรียกใช้งานฟังก์ชัน add โดยส่งค่า 5 และ 7 ไป
    // และสร้างตัวแปร sum มารอรับค่าที่ฟังก์ชันส่งกลับมา
    int sum = add(5, 7); 

    printf("5 + 7 = %d\n", sum);

    return 0;
}
